WITH flattened AS (SELECT id, plan, effective_from, EXPLODE_OUTER(tier_limits) AS tier_value FROM price_tiers) SELECT CASE WHEN tier_value >= 85 THEN 'HIGH' ELSE 'LOW' END AS tier_value_tier, SUM(CASE WHEN plan = 'starter' THEN tier_value ELSE 0 END) AS starter_tier_value, SUM(CASE WHEN plan = 'starter' THEN tier_value ELSE 0 END) AS starter_tier_value_2, COUNT(DISTINCT id) AS distinct_ids, SIZE(COLLECT_SET(plan)) AS num_plans, SIZE(COLLECT_SET(plan)) AS num_plans_2, SUM(CASE WHEN plan = 'starter' THEN tier_value ELSE 0 END) AS starter_tier_value_3 FROM flattened GROUP BY tier_value_tier ORDER BY tier_value_tier NULLS LAST;
